alter table public.saving_goals add column funded_at timestamptz,add column cycle_funded_at timestamptz,add column recurrence_unit text check(recurrence_unit in('MONTH','YEAR')),add column recurrence_interval integer check(recurrence_interval in(1,3,6)),add column cycle_anchor_date date,add column current_cycle_start date,add column current_cycle_end date;
alter table public.saving_goal_dispositions add column amount bigint not null default 0 check(amount>=0);
create table public.saving_goal_cycles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,goal_id uuid not null,cycle_start date not null,cycle_end date not null,opening_amount bigint not null check(opening_amount>=0),closing_amount bigint,reset_at timestamptz,operation_key text not null,created_at timestamptz not null default now(),unique(user_id,operation_key),unique(goal_id,cycle_start),foreign key(goal_id,user_id) references public.saving_goals(id,user_id) on delete cascade);
create index saving_goal_cycles_goal_user_idx on public.saving_goal_cycles(goal_id,user_id);
alter table public.saving_goal_cycles enable row level security;
create policy saving_goal_cycles_read on public.saving_goal_cycles for select to authenticated using((select auth.uid())=user_id);
revoke all on public.saving_goal_cycles from anon,authenticated;
grant select on public.saving_goal_cycles to authenticated;
create function public.saving_cycle_end(p_start date,p_unit text,p_interval integer,p_anchor_day integer) returns date language plpgsql immutable set search_path='' as $$ declare base date; last_day integer; begin base:=case when p_unit='YEAR' then make_date(extract(year from p_start)::integer+p_interval,extract(month from p_start)::integer,1) else (date_trunc('month',p_start)+(p_interval||' months')::interval)::date end; last_day:=extract(day from (base+interval '1 month'-interval '1 day'))::integer; return base+least(p_anchor_day,last_day)-1; end $$;
create function public.sync_saving_goal_lifecycle() returns trigger language plpgsql set search_path='' as $$ begin if new.saved_amount>=new.target_amount then new.lifecycle_status='FUNDED';new.funded_at=coalesce(old.funded_at,now());new.cycle_funded_at=coalesce(old.cycle_funded_at,now());elsif old.lifecycle_status='FUNDED' then new.lifecycle_status='ACTIVE';new.funded_at=null;end if;if new.target_amount<new.saved_amount then raise exception 'TARGET_BELOW_SAVED' using errcode='P0001';end if;return new;end $$;
create trigger saving_goals_lifecycle before update of saved_amount,target_amount on public.saving_goals for each row execute function public.sync_saving_goal_lifecycle();
update public.saving_goals set lifecycle_status='FUNDED',funded_at=coalesce(funded_at,updated_at) where saved_amount>=target_amount;
create function public.upsert_saving_goal(p_goal_id uuid,p_name text,p_target_amount bigint,p_target_date date,p_recurrence_unit text,p_recurrence_interval integer,p_expected_version integer) returns public.saving_goals language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();g public.saving_goals;s date;e date;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if nullif(btrim(p_name),'') is null or p_target_amount<1 or p_recurrence_unit is not null and (p_recurrence_unit not in('MONTH','YEAR') or p_recurrence_interval not in(1,3,6) or p_recurrence_unit='YEAR' and p_recurrence_interval<>1) then raise exception 'INVALID_GOAL' using errcode='P0001';end if;s:=coalesce(p_target_date,current_date);e:=case when p_recurrence_unit is null then null else public.saving_cycle_end(s,p_recurrence_unit,p_recurrence_interval,extract(day from s)::integer) end;if p_goal_id is null then insert into public.saving_goals(user_id,name,target_amount,target_date,recurrence_unit,recurrence_interval,cycle_anchor_date,current_cycle_start,current_cycle_end) values(u,btrim(p_name),p_target_amount,p_target_date,p_recurrence_unit,p_recurrence_interval,case when p_recurrence_unit is null then null else s end,case when p_recurrence_unit is null then null else s end,e) returning * into g;else select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update;if not found then raise exception 'GOAL_NOT_FOUND' using errcode='P0001';end if;if g.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001';end if;if p_target_amount<g.saved_amount then raise exception 'TARGET_BELOW_SAVED' using errcode='P0001';end if;update public.saving_goals set name=btrim(p_name),target_amount=p_target_amount,target_date=p_target_date,recurrence_unit=p_recurrence_unit,recurrence_interval=p_recurrence_interval,cycle_anchor_date=case when p_recurrence_unit is null then null else coalesce(g.cycle_anchor_date,s) end,current_cycle_start=case when p_recurrence_unit is null then null else coalesce(g.current_cycle_start,s) end,current_cycle_end=case when p_recurrence_unit is null then null else public.saving_cycle_end(coalesce(g.current_cycle_start,s),p_recurrence_unit,p_recurrence_interval,extract(day from coalesce(g.cycle_anchor_date,s))::integer) end where id=g.id returning * into g;end if;return g;end $$;
create function public.reset_saving_goal_cycle(p_goal_id uuid,p_expected_version integer,p_operation_key text) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();g public.saving_goals;r public.saving_goal_cycles;next_start date;next_end date;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;select * into r from public.saving_goal_cycles where user_id=u and operation_key=p_operation_key;if found then return jsonb_build_object('cycle',to_jsonb(r),'replayed',true);end if;select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update;if not found or g.recurrence_unit is null then raise exception 'RECURRING_GOAL_NOT_FOUND' using errcode='P0001';end if;if g.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001';end if;if g.cycle_funded_at is null then raise exception 'GOAL_NOT_READY_TO_RESET' using errcode='P0001';end if;next_start:=g.current_cycle_end;next_end:=public.saving_cycle_end(next_start,g.recurrence_unit,g.recurrence_interval,extract(day from g.cycle_anchor_date)::integer);insert into public.saving_goal_cycles(user_id,goal_id,cycle_start,cycle_end,opening_amount,closing_amount,reset_at,operation_key) values(u,g.id,g.current_cycle_start,g.current_cycle_end,g.saved_amount,g.saved_amount,now(),p_operation_key) returning * into r;update public.saving_goals set current_cycle_start=next_start,current_cycle_end=next_end,cycle_funded_at=case when saved_amount>=target_amount then now() else null end,lifecycle_status=case when saved_amount>=target_amount then 'FUNDED' else 'ACTIVE' end where id=g.id;return jsonb_build_object('cycle',to_jsonb(r),'carried_amount',g.saved_amount,'replayed',false);end $$;
create function public.get_saving_goal_recovery(p_goal_id uuid) returns jsonb language plpgsql security definer set search_path='' stable as $$ declare u uuid:=auth.uid();g public.saving_goals;required bigint;months integer;begin select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null;if not found then raise exception 'GOAL_NOT_FOUND' using errcode='P0001';end if;months:=case when g.target_date is null then null else greatest((extract(year from g.target_date)::integer-extract(year from current_date)::integer)*12+extract(month from g.target_date)::integer-extract(month from current_date)::integer+1,1) end;required:=case when months is null then null else ceil(greatest(g.target_amount-g.saved_amount,0)::numeric/months)::bigint end;return jsonb_build_object('status',case when g.lifecycle_status='FUNDED' then 'FUNDED' when g.target_date<current_date then 'OVERDUE' when required is null then 'UNSCHEDULED' else 'ACTIVE' end,'required_monthly',required,'plans',jsonb_build_array(jsonb_build_object('kind','CONTRIBUTE','amount',required),jsonb_build_object('kind','EXTEND','months',coalesce(months,1)),jsonb_build_object('kind','REDUCE_TARGET','minimum',g.saved_amount)));end $$;
create function public.get_balance_breakdown() returns jsonb language sql security definer set search_path='' stable as $$ with a as(select coalesce(sum(balance),0)::bigint gross from public.accounts where user_id=(select auth.uid()) and deleted_at is null),p as(select coalesce(sum(locked_amount),0)::bigint protected from public.saving_virtual_locks where user_id=(select auth.uid())) select jsonb_build_object('gross_balance',a.gross,'protected_balance',p.protected,'free_balance',greatest(a.gross-p.protected,0)) from a,p $$;
create or replace function public.get_parser_finance_preview(p_account_id uuid,p_amount bigint,p_type public.transaction_type) returns jsonb language plpgsql security definer set search_path='' stable as $$ declare u uuid:=auth.uid();a public.accounts;locked bigint;safe bigint;goals jsonb;debts jsonb;impacts jsonb;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if p_amount<1 then raise exception 'INVALID_MONEY' using errcode='P0001';end if;select * into a from public.accounts where id=p_account_id and user_id=u and deleted_at is null;if not found then raise exception 'ACCOUNT_NOT_FOUND' using errcode='P0001';end if;select coalesce(sum(locked_amount),0) into locked from public.saving_virtual_locks where account_id=a.id and user_id=u;safe:=greatest(a.balance-locked,0);select coalesce(jsonb_agg(jsonb_build_object('goal_id',goal_id,'name',name,'amount',amount) order by rank),'[]') into impacts from(select g.id goal_id,g.name,least(v.locked_amount,greatest(p_amount-safe-coalesce(sum(v.locked_amount) over(order by case g.priority when 'LOW' then 1 when 'NORMAL' then 2 when 'HIGH' then 3 else 4 end,g.id rows between unbounded preceding and 1 preceding),0),0)) amount,row_number() over(order by case g.priority when 'LOW' then 1 when 'NORMAL' then 2 when 'HIGH' then 3 else 4 end,g.id) rank from public.saving_virtual_locks v join public.saving_goals g on g.id=v.goal_id where v.account_id=a.id and v.user_id=u)s where amount>0;select '[]'::jsonb,'[]'::jsonb into goals,debts;return jsonb_build_object('gross_balance',a.balance,'protected_amount',locked,'free_balance',safe,'protected_shortfall',case when p_type='EXPENSE' then greatest(p_amount-safe,0) else 0 end,'recovery_impacts',impacts,'goals',goals,'debts',debts,'free_remainder',p_amount);end $$;
create or replace function public.apply_windfall_split(p_account_id uuid,p_amount bigint,p_category_name text,p_description text,p_allocations jsonb,p_operation_key text) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();x jsonb;total bigint:=0;value bigint;g public.saving_goals;d public.debts;t public.transactions;category_id uuid;begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001';end if;if p_amount<1 or jsonb_typeof(p_allocations)<>'array' or char_length(coalesce(p_operation_key,''))<8 then raise exception 'INVALID_WINDFALL_SPLIT' using errcode='P0001';end if;select * into t from public.transactions where user_id=u and operation_key=p_operation_key;if found then select coalesce(sum((e->>'amount')::bigint),0) into total from jsonb_array_elements(p_allocations)e;return jsonb_build_object('transaction_id',t.id,'allocated',total,'free_remainder',p_amount-total,'replayed',true);end if;select 1 from public.accounts where id=p_account_id and user_id=u and deleted_at is null for update;if not found then raise exception 'ACCOUNT_NOT_FOUND' using errcode='P0001';end if;select coalesce(sum((e->>'amount')::bigint),0) into total from jsonb_array_elements(p_allocations)e;if total>p_amount or total<0 then raise exception 'INVALID_WINDFALL_SPLIT' using errcode='P0001';end if;select id into category_id from public.categories where user_id=u and deleted_at is null and type='INCOME' and lower(name)=lower(btrim(p_category_name)) order by created_at limit 1;t:=public.create_money_transaction(p_account_id,'INCOME',p_amount,category_id,null,p_description,null,now(),'PARSER');update public.transactions set operation_key=p_operation_key where id=t.id returning * into t;for x in select * from jsonb_array_elements(p_allocations) loop value:=(x->>'amount')::bigint;if value<1 then continue;end if;if x->>'kind'='GOAL' then select * into g from public.saving_goals where id=(x->>'id')::uuid and user_id=u and deleted_at is null and lifecycle_status='ACTIVE' for update;if not found or value>g.target_amount-g.saved_amount then raise exception 'INVALID_GOAL_ALLOCATION' using errcode='P0001';end if;perform public.record_saving_goal_mutation_v3(g.id,p_account_id,'DEPOSIT',value,'Pembagian pemasukan tak terduga',g.version,p_operation_key||'-goal-'||g.id);elsif x->>'kind'='DEBT' then select * into d from public.debts where id=(x->>'id')::uuid and user_id=u and deleted_at is null for update;if not found or value>d.total_amount-d.paid_amount then raise exception 'INVALID_DEBT_ALLOCATION' using errcode='P0001';end if;perform public.record_debt_payment_v2(d.id,p_account_id,value,'Pembagian pemasukan tak terduga',now(),d.version,p_operation_key||'-debt-'||d.id);else raise exception 'INVALID_WINDFALL_SPLIT' using errcode='P0001';end if;end loop;return jsonb_build_object('transaction_id',t.id,'allocated',total,'free_remainder',p_amount-total,'replayed',false);end $$;
revoke execute on function public.saving_cycle_end(date,text,integer,integer),public.sync_saving_goal_lifecycle(),public.upsert_saving_goal(uuid,text,bigint,date,text,integer,integer),public.reset_saving_goal_cycle(uuid,integer,text),public.get_saving_goal_recovery(uuid),public.get_balance_breakdown() from public,anon,authenticated;
grant execute on function public.upsert_saving_goal(uuid,text,bigint,date,text,integer,integer),public.reset_saving_goal_cycle(uuid,integer,text),public.get_saving_goal_recovery(uuid),public.get_balance_breakdown() to authenticated;
revoke execute on function public.create_saving_goal(text,bigint,date),public.create_money_transaction(uuid,public.transaction_type,bigint,uuid,text,text,text,timestamptz,public.transaction_source),public.record_saving_goal_mutation(uuid,public.saving_mutation_kind,bigint,text,timestamptz,integer),public.record_saving_goal_mutation_v2(uuid,uuid,public.saving_mutation_kind,bigint,text,timestamptz,integer,text) from authenticated;
